-- Section 213: Reading Passage 3: Book review: The World of Sugar by Ulbe Bosma
INSERT INTO sections (id, test_id, type, title, instructions, audio_url, passage_text, order_index) VALUES
(213, 21, 'reading', 'Reading Passage 3: Book review: The World of Sugar by Ulbe Bosma', '<div class="ielts-reading-container"><h2 class="ielts-reading-question-section-heading">
                                            Questions 27-30                                                                                                                                                
                                                                                                                                    </h2>
                                        <div class="ielts-reading-question-section-content">
                                            <p>Choose the correct letter, A, B, C or D.</p>
                                        </div>
                                        <div class="ielts-reading-questions">
                                                                                                                                                                                            <div class="ielts-standalone-q" data-qnum="27"><div class="ielts-q-header"><strong class="ielts-q-badge">27</strong><span class="ielts-q-title">What does the reviewer suggest about the cultivation and trading of sugar in the first paragraph?</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="27" name="question_27" value="A"><span class="ielts-radio-text"><strong>A</strong> Sugar has played a major role in international relations.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="27" name="question_27" value="B"><span class="ielts-radio-text"><strong>B</strong> Beet sugar has been made more internationally competitive.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="27" name="question_27" value="C"><span class="ielts-radio-text"><strong>C</strong> Cane sugar is thought to be of superior quality to beet sugar.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="27" name="question_27" value="D"><span class="ielts-radio-text"><strong>D</strong> New locations for cultivating sugar have increased production.</span></label></div></div><div class="ielts-standalone-q" data-qnum="28"><div class="ielts-q-header"><strong class="ielts-q-badge">28</strong><span class="ielts-q-title">In the second paragraph, when discussing the sugar market in Britain, the reviewer stresses</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="28" name="question_28" value="A"><span class="ielts-radio-text"><strong>A</strong> how the sources used changed over time.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="28" name="question_28" value="B"><span class="ielts-radio-text"><strong>B</strong> how developments in agriculture affected trade.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="28" name="question_28" value="C"><span class="ielts-radio-text"><strong>C</strong> the increased demand for sugar over the years.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="28" name="question_28" value="D"><span class="ielts-radio-text"><strong>D</strong> the growing support for ethical methods of cultivation.</span></label></div></div><div class="ielts-standalone-q" data-qnum="29"><div class="ielts-q-header"><strong class="ielts-q-badge">29</strong><span class="ielts-q-title">What is the reviewer doing in the third paragraph?</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="29" name="question_29" value="A"><span class="ielts-radio-text"><strong>A</strong> describing an efficient approach to sugar cultivation</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="29" name="question_29" value="B"><span class="ielts-radio-text"><strong>B</strong> explaining why the use of sugar plantations declined</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="29" name="question_29" value="C"><span class="ielts-radio-text"><strong>C</strong> addressing a misconception about the growing of sugar cane</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="29" name="question_29" value="D"><span class="ielts-radio-text"><strong>D</strong> evaluating different approaches to the cultivation of sugar cane</span></label></div></div><div class="ielts-standalone-q" data-qnum="30"><div class="ielts-q-header"><strong class="ielts-q-badge">30</strong><span class="ielts-q-title">In the final paragraph, what does the reviewer suggest is the overall message of Bosma''s book?</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="30" name="question_30" value="A"><span class="ielts-radio-text"><strong>A</strong> Sugar is a harmful and unnecessary product.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="30" name="question_30" value="B"><span class="ielts-radio-text"><strong>B</strong> Economic pressure is needed to control sugar production.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="30" name="question_30" value="C"><span class="ielts-radio-text"><strong>C</strong> Conditions for workers in sugar production should be improved.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="30" name="question_30" value="D"><span class="ielts-radio-text"><strong>D</strong> Intensive marketing of sugar has had disastrous consequences.</span></label></div></div></div>
                                                                                                                                    </div>
                                                                                                                                                            <h2 class="ielts-reading-question-section-heading">
                                            Questions 31-36                                                                                                                                                
                                                                                                                                    </h2>
                                        <div class="ielts-reading-question-section-content">
                                            <div class="ielts-reading-section-content-wrapper"><p>Complete the summary using the list of words, A-I, below.</p>
<p><strong>Sugar cultivation and production</strong></p>
<p>The book The World of Sugar points out the similarities in the way that sugar was cultivated around the world. In the big industries in both Germany and the US, sugar farming depended on <span class="ielts-reading-question-item"><span class="ielts-inline-select-wrap"><strong class="ielts-q-badge">31</strong><select data-qnum="31" name="question_31" class="ielts-inline-select"><option value="">[ 31 ] Tanlang...</option><option value="A. national governments">A. national governments</option><option value="B. agricultural developments">B. agricultural developments</option><option value="C. less wealthy nations">C. less wealthy nations</option><option value="D. untrained workers">D. untrained workers</option><option value="E. small-scale cultivation">E. small-scale cultivation</option><option value="F. outdated methods">F. outdated methods</option><option value="G. financial controls">G. financial controls</option><option value="H. migrant workers">H. migrant workers</option><option value="I. powerful individuals and businesses">I. powerful individuals and businesses</option></select></span></span> . However, in other parts of the world such as South Asia and Latin America, <span class="ielts-reading-question-item"><span class="ielts-inline-select-wrap"><strong class="ielts-q-badge">32</strong><select data-qnum="32" name="question_32" class="ielts-inline-select"><option value="">[ 32 ] Tanlang...</option><option value="A. national governments">A. national governments</option><option value="B. agricultural developments">B. agricultural developments</option><option value="C. less wealthy nations">C. less wealthy nations</option><option value="D. untrained workers">D. untrained workers</option><option value="E. small-scale cultivation">E. small-scale cultivation</option><option value="F. outdated methods">F. outdated methods</option><option value="G. financial controls">G. financial controls</option><option value="H. migrant workers">H. migrant workers</option><option value="I. powerful individuals and businesses">I. powerful individuals and businesses</option></select></span></span> continued.</p>
<p>Sugar production has also involved <span class="ielts-reading-question-item"><span class="ielts-inline-select-wrap"><strong class="ielts-q-badge">33</strong><select data-qnum="33" name="question_33" class="ielts-inline-select"><option value="">[ 33 ] Tanlang...</option><option value="A. national governments">A. national governments</option><option value="B. agricultural developments">B. agricultural developments</option><option value="C. less wealthy nations">C. less wealthy nations</option><option value="D. untrained workers">D. untrained workers</option><option value="E. small-scale cultivation">E. small-scale cultivation</option><option value="F. outdated methods">F. outdated methods</option><option value="G. financial controls">G. financial controls</option><option value="H. migrant workers">H. migrant workers</option><option value="I. powerful individuals and businesses">I. powerful individuals and businesses</option></select></span></span> who were eager to protect their markets. In countries such as Cuba the sugar industry therefore had a major influence on <span class="ielts-reading-question-item"><span class="ielts-inline-select-wrap"><strong class="ielts-q-badge">34</strong><select data-qnum="34" name="question_34" class="ielts-inline-select"><option value="">[ 34 ] Tanlang...</option><option value="A. national governments">A. national governments</option><option value="B. agricultural developments">B. agricultural developments</option><option value="C. less wealthy nations">C. less wealthy nations</option><option value="D. untrained workers">D. untrained workers</option><option value="E. small-scale cultivation">E. small-scale cultivation</option><option value="F. outdated methods">F. outdated methods</option><option value="G. financial controls">G. financial controls</option><option value="H. migrant workers">H. migrant workers</option><option value="I. powerful individuals and businesses">I. powerful individuals and businesses</option></select></span></span> .</p>
<p>To support the interests of sugar producers, <span class="ielts-reading-question-item"><span class="ielts-inline-select-wrap"><strong class="ielts-q-badge">35</strong><select data-qnum="35" name="question_35" class="ielts-inline-select"><option value="">[ 35 ] Tanlang...</option><option value="A. national governments">A. national governments</option><option value="B. agricultural developments">B. agricultural developments</option><option value="C. less wealthy nations">C. less wealthy nations</option><option value="D. untrained workers">D. untrained workers</option><option value="E. small-scale cultivation">E. small-scale cultivation</option><option value="F. outdated methods">F. outdated methods</option><option value="G. financial controls">G. financial controls</option><option value="H. migrant workers">H. migrant workers</option><option value="I. powerful individuals and businesses">I. powerful individuals and businesses</option></select></span></span> were established. As a result of this, <span class="ielts-reading-question-item"><span class="ielts-inline-select-wrap"><strong class="ielts-q-badge">36</strong><select data-qnum="36" name="question_36" class="ielts-inline-select"><option value="">[ 36 ] Tanlang...</option><option value="A. national governments">A. national governments</option><option value="B. agricultural developments">B. agricultural developments</option><option value="C. less wealthy nations">C. less wealthy nations</option><option value="D. untrained workers">D. untrained workers</option><option value="E. small-scale cultivation">E. small-scale cultivation</option><option value="F. outdated methods">F. outdated methods</option><option value="G. financial controls">G. financial controls</option><option value="H. migrant workers">H. migrant workers</option><option value="I. powerful individuals and businesses">I. powerful individuals and businesses</option></select></span></span> were penalised.</p>
