-- Section 221: Reading Passage 1: Do animals dream?
INSERT INTO sections (id, test_id, type, title, instructions, audio_url, passage_text, order_index) VALUES
(221, 22, 'reading', 'Reading Passage 1: Do animals dream?', '<div class="ielts-reading-container"><h2 class="ielts-reading-question-section-heading">
                                            Questions 1-5                                                                                                                                                                                                    
                                                                                                                                    </h2>
                                        <div class="ielts-reading-question-section-content">
                                            <p>Complete the table below.</p>
<p>Choose ONE WORD ONLY from the passage for each answer.</p>
<table>
<thead>
<tr>
<th colspan="3">Research into sleep and dreaming</th>
</tr>
<tr>
<th></th>
<th>Research findings</th>
<th>Comment</th>
</tr>
</thead>
<tbody>
<tr>
<td>Humans</td>
<td>
<ul>
<li>humans experience REM sleep and non-REM sleep</li>
<li>in REM sleep, the eyes and muscles move</li>
</ul>
</td>
<td></td>
