-- Section 231: Reading Passage 1: Saving the saiga
INSERT INTO sections (id, test_id, type, title, instructions, audio_url, passage_text, order_index) VALUES
(231, 23, 'reading', 'Reading Passage 1: Saving the saiga', '<div class="ielts-reading-container"><h2 class="ielts-reading-question-section-heading">
                                            Questions 1-7                                                                                                                                                                                                    
                                                                                                                                    </h2>
                                        <div class="ielts-reading-question-section-content">
                                            <div class="ielts-reading-section-content-wrapper"><p>Complete the notes below.</p>
<p>Choose ONE WORD ONLY from the passage for each answer.</p>
<p><strong>The saiga</strong></p>
<p><strong>Adaptations</strong></p>
<ul>
<li>has a large bulbous nose with swollen nostrils that</p>
<p>- keep <span class="ielts-reading-question-item"><span class="ielts-inline-input-wrap"><strong class="ielts-q-badge">1</strong><input type="text" data-qnum="1" name="question_1" class="ielts-inline-input" placeholder="[1] javob..." autocomplete="off" spellcheck="false"></span></span> out</p>
<p>- lower the temperature of its <span class="ielts-reading-question-item"><span class="ielts-inline-input-wrap"><strong class="ielts-q-badge">2</strong><input type="text" data-qnum="2" name="question_2" class="ielts-inline-input" placeholder="[2] javob..." autocomplete="off" spellcheck="false"></span></span> in summer</p>
<p>- warm the air entering its lungs in winter</li>
