INSERT INTO sections (id, test_id, type, title, instructions, audio_url, passage_text, order_index) VALUES
(241, 24, 'reading', 'Reading Passage 1: The problems and benefits created by the spread of the water hyacinth in Kenya', '<div class="ielts-reading-container"><h2 class="ielts-reading-question-section-heading">
                                            Questions 1-7                                                                                                                                                                                                    
                                                                                                                                    </h2>
                                        <div class="ielts-reading-question-section-content">
                                            <p>Do the following statements agree with the information given in Reading Passage 1?</p>
                                        </div>
                                        <div class="ielts-reading-questions">
                                                                                                                                                                                            <div class="ielts-standalone-q" data-qnum="1"><div class="ielts-q-header"><strong class="ielts-q-badge">1</strong><span class="ielts-q-title">Water hyacinth was introduced as a decorative plant in east Africa.</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="1" name="question_1" value="TRUE"><span class="ielts-radio-text"><strong>TRUE</strong> </span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="1" name="question_1" value="FALSE"><span class="ielts-radio-text"><strong>FALSE</strong> </span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="1" name="question_1" value="NOT GIVEN"><span class="ielts-radio-text"><strong>NOT GIVEN</strong> </span></label></div></div><div class="ielts-standalone-q" data-qnum="2"><div class="ielts-q-header"><strong class="ielts-q-badge">2</strong><span class="ielts-q-title">Fishermen took some water hyacinth plants to Lake Victoria.</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="2" name="question_2" value="TRUE"><span class="ielts-radio-text"><strong>TRUE</strong> </span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="2" name="question_2" value="FALSE"><span class="ielts-radio-text"><strong>FALSE</strong> </span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="2" name="question_2" value="NOT GIVEN"><span class="ielts-radio-text"><strong>NOT GIVEN</strong> </span></label></div></div><div class="ielts-standalone-q" data-qnum="3"><div class="ielts-q-header"><strong class="ielts-q-badge">3</strong><span class="ielts-q-title">It is now difficult to force boats through the thick water hyacinth on Lake Victoria.</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="3" name="question_3" value="TRUE"><span class="ielts-radio-text"><strong>TRUE</strong> </span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="3" name="question_3" value="FALSE"><span class="ielts-radio-text"><strong>FALSE</strong> </span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="3" name="question_3" value="NOT GIVEN"><span class="ielts-radio-text"><strong>NOT GIVEN</strong> </span></label></div></div><div class="ielts-standalone-q" data-qnum="4"><div class="ielts-q-header"><strong class="ielts-q-badge">4</strong><span class="ielts-q-title">Chemicals produced by the water hyacinth plants are affecting the numbers of fish in Lake Victoria.</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="4" name="question_4" value="TRUE"><span class="ielts-radio-text"><strong>TRUE</strong> </span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="4" name="question_4" value="FALSE"><span class="ielts-radio-text"><strong>FALSE</strong> </span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="4" name="question_4" value="NOT GIVEN"><span class="ielts-radio-text"><strong>NOT GIVEN</strong> </span></label></div></div><div class="ielts-standalone-q" data-qnum="5"><div class="ielts-q-header"><strong class="ielts-q-badge">5</strong><span class="ielts-q-title">Cooking with charcoal has been proved to be even worse for people''s health than cooking with wood.</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="5" name="question_5" value="TRUE"><span class="ielts-radio-text"><strong>TRUE</strong> </span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="5" name="question_5" value="FALSE"><span class="ielts-radio-text"><strong>FALSE</strong> </span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="5" name="question_5" value="NOT GIVEN"><span class="ielts-radio-text"><strong>NOT GIVEN</strong> </span></label></div></div><div class="ielts-standalone-q" data-qnum="6"><div class="ielts-q-header"><strong class="ielts-q-badge">6</strong><span class="ielts-q-title">People found it impossible to remove much water hyacinth from Lake Victoria.</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="6" name="question_6" value="TRUE"><span class="ielts-radio-text"><strong>TRUE</strong> </span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="6" name="question_6" value="FALSE"><span class="ielts-radio-text"><strong>FALSE</strong> </span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="6" name="question_6" value="NOT GIVEN"><span class="ielts-radio-text"><strong>NOT GIVEN</strong> </span></label></div></div><div class="ielts-standalone-q" data-qnum="7"><div class="ielts-q-header"><strong class="ielts-q-badge">7</strong><span class="ielts-q-title">Scientists started investigating the possibility of using water hyacinth to generate biogas in the last century.</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="7" name="question_7" value="TRUE"><span class="ielts-radio-text"><strong>TRUE</strong> </span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="7" name="question_7" value="FALSE"><span class="ielts-radio-text"><strong>FALSE</strong> </span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="7" name="question_7" value="NOT GIVEN"><span class="ielts-radio-text"><strong>NOT GIVEN</strong> </span></label></div></div></div>
                                                                                                                                    </div>
                                                                                                                                                            <h2 class="ielts-reading-question-section-heading">
                                            Questions 8-10                                                                                                                                                
                                                                                                                                    </h2>
                                        <div class="ielts-reading-question-section-content">
                                            <div class="ielts-reading-section-content-wrapper"><p>Complete the flow-chart below.</p>
<p>Choose NO MORE THAN TWO WORDS from the passage for each answer.</p>
<p><strong>Generating biogas for domestic use in Dunga</strong></p>
<p>First, place water hyacinth together with some <span class="ielts-reading-question-item"><span class="ielts-inline-input-wrap"><strong class="ielts-q-badge">8</strong><input type="text" data-qnum="8" name="question_8" class="ielts-inline-input" placeholder="[8] javob..." autocomplete="off" spellcheck="false"></span></span> into a digester</p>
<p>↓</p>
