-- Section 243: Reading Passage 3: The Globemakers: The Curious Story of an Ancient Craft
INSERT INTO sections (id, test_id, type, title, instructions, audio_url, passage_text, order_index) VALUES
(243, 24, 'reading', 'Reading Passage 3: The Globemakers: The Curious Story of an Ancient Craft', '<div class="ielts-reading-container"><h2 class="ielts-reading-question-section-heading">
                                            Questions 27-32                                                                                                                                                
                                                                                                                                    </h2>
                                        <div class="ielts-reading-question-section-content">
                                            <div class="ielts-reading-section-content-wrapper"><p>Complete the summary using the list of words, A-J, below.</p>
<p><strong>A birthday gift</strong></p>
<p>Peter Bellerby''s plan to give his father a globe for his birthday was an unexpectedly <span class="ielts-reading-question-item"><span class="ielts-inline-select-wrap"><strong class="ielts-q-badge">27</strong><select data-qnum="27" name="question_27" class="ielts-inline-select"><option value="">[ 27 ] Tanlang...</option><option value="A. educational use">A. educational use</option><option value="B. rare materials">B. rare materials</option><option value="C. inferior makes">C. inferior makes</option><option value="D. product exchange markets">D. product exchange markets</option><option value="E. necessary skills">E. necessary skills</option><option value="F. international">F. international</option><option value="G. challenging task">G. challenging task</option><option value="H. memorable object">H. memorable object</option><option value="I. internet purchase">I. internet purchase</option><option value="J. numerous problems">J. numerous problems</option></select></span></span> for which he had to overcome <span class="ielts-reading-question-item"><span class="ielts-inline-select-wrap"><strong class="ielts-q-badge">28</strong><select data-qnum="28" name="question_28" class="ielts-inline-select"><option value="">[ 28 ] Tanlang...</option><option value="A. educational use">A. educational use</option><option value="B. rare materials">B. rare materials</option><option value="C. inferior makes">C. inferior makes</option><option value="D. product exchange markets">D. product exchange markets</option><option value="E. necessary skills">E. necessary skills</option><option value="F. international">F. international</option><option value="G. challenging task">G. challenging task</option><option value="H. memorable object">H. memorable object</option><option value="I. internet purchase">I. internet purchase</option><option value="J. numerous problems">J. numerous problems</option></select></span></span>.</p>
<p>He soon learnt that a straightforward <span class="ielts-reading-question-item"><span class="ielts-inline-select-wrap"><strong class="ielts-q-badge">29</strong><select data-qnum="29" name="question_29" class="ielts-inline-select"><option value="">[ 29 ] Tanlang...</option><option value="A. educational use">A. educational use</option><option value="B. rare materials">B. rare materials</option><option value="C. inferior makes">C. inferior makes</option><option value="D. product exchange markets">D. product exchange markets</option><option value="E. necessary skills">E. necessary skills</option><option value="F. international">F. international</option><option value="G. challenging task">G. challenging task</option><option value="H. memorable object">H. memorable object</option><option value="I. internet purchase">I. internet purchase</option><option value="J. numerous problems">J. numerous problems</option></select></span></span> would not be possible. Some <span class="ielts-reading-question-item"><span class="ielts-inline-select-wrap"><strong class="ielts-q-badge">30</strong><select data-qnum="30" name="question_30" class="ielts-inline-select"><option value="">[ 30 ] Tanlang...</option><option value="A. educational use">A. educational use</option><option value="B. rare materials">B. rare materials</option><option value="C. inferior makes">C. inferior makes</option><option value="D. product exchange markets">D. product exchange markets</option><option value="E. necessary skills">E. necessary skills</option><option value="F. international">F. international</option><option value="G. challenging task">G. challenging task</option><option value="H. memorable object">H. memorable object</option><option value="I. internet purchase">I. internet purchase</option><option value="J. numerous problems">J. numerous problems</option></select></span></span> that had been intended for <span class="ielts-reading-question-item"><span class="ielts-inline-select-wrap"><strong class="ielts-q-badge">31</strong><select data-qnum="31" name="question_31" class="ielts-inline-select"><option value="">[ 31 ] Tanlang...</option><option value="A. educational use">A. educational use</option><option value="B. rare materials">B. rare materials</option><option value="C. inferior makes">C. inferior makes</option><option value="D. product exchange markets">D. product exchange markets</option><option value="E. necessary skills">E. necessary skills</option><option value="F. international">F. international</option><option value="G. challenging task">G. challenging task</option><option value="H. memorable object">H. memorable object</option><option value="I. internet purchase">I. internet purchase</option><option value="J. numerous problems">J. numerous problems</option></select></span></span> were available, as were some expensive antique globes, but these were beyond his budget. He even travelled to places where people might still have the <span class="ielts-reading-question-item"><span class="ielts-inline-select-wrap"><strong class="ielts-q-badge">32</strong><select data-qnum="32" name="question_32" class="ielts-inline-select"><option value="">[ 32 ] Tanlang...</option><option value="A. educational use">A. educational use</option><option value="B. rare materials">B. rare materials</option><option value="C. inferior makes">C. inferior makes</option><option value="D. product exchange markets">D. product exchange markets</option><option value="E. necessary skills">E. necessary skills</option><option value="F. international">F. international</option><option value="G. challenging task">G. challenging task</option><option value="H. memorable object">H. memorable object</option><option value="I. internet purchase">I. internet purchase</option><option value="J. numerous problems">J. numerous problems</option></select></span></span>, but Bellerby could not find what he wanted.</p>
</div>                                                <div class="options-dnd-panel dnd-panel dnd-panel--inline" data-dnd-group="3178476">
